// 1) 简单工厂：对照 Calendar.getInstance 的思路
public class PaymentFactory {
    public static Payment create(String channel) {
        switch (channel) {
            case "alipay": return new AlipayPayment();
            case "wechat": return new WechatPayment();
            default: throw new IllegalArgumentException("unknown channel: " + channel);
        }
    }
}

// 2) 工厂方法：对照 Collection#iterator
public interface PaymentCreator {
    Payment create();
}
public class AlipayCreator implements PaymentCreator {
    @Override public Payment create() { return new AlipayPayment(); }
}
public class WechatCreator implements PaymentCreator {
    @Override public Payment create() { return new WechatPayment(); }
}
// 新增 UnionPay：只加 UnionPayCreator，不动现有代码（开闭）

// 3) 抽象工厂：一族相关产品（支付 + 退款 + 对账）
public interface ChannelFactory {
    Payment payment();
    Refund refund();
    Reconciliation reconciliation();
}
public class AlipayChannelFactory implements ChannelFactory {
    @Override public Payment payment() { return new AlipayPayment(); }
    @Override public Refund refund() { return new AlipayRefund(); }
    @Override public Reconciliation reconciliation() { return new AlipayRecon(); }
}
// 切换为微信渠道：只换 WechatChannelFactory，三件套整族切换
// 但若新增「订阅 Subscription」产品，所有 ChannelFactory 实现都得改

// 4) Spring FactoryBean：把复杂创建过程封装成一个 Bean
public class RedisClientFactoryBean implements FactoryBean<RedisClient> {
    private String host; private int port; private int timeoutMs;
    @Override public RedisClient getObject() throws Exception {
        return RedisClient.create(RedisURI.builder()
                .withHost(host).withPort(port)
                .withTimeout(Duration.ofMillis(timeoutMs)).build());
    }
    @Override public Class<?> getObjectType() { return RedisClient.class; }
    @Override public boolean isSingleton() { return true; }
}
// getBean("redisClient") -> 拿到 RedisClient（getObject 返回值）
// getBean("&redisClient") -> 拿到 RedisClientFactoryBean 本身

// 5) DI 视角：@Bean 方法 = 声明式工厂方法，容器决定何时调
@Configuration
public class PaymentConfig {
    @Bean
    @ConditionalOnProperty(name = "pay.channel", havingValue = "alipay")
    public Payment alipayPayment() { return new AlipayPayment(); }
    @Bean
    @ConditionalOnProperty(name = "pay.channel", havingValue = "wechat")
    public Payment wechatPayment() { return new WechatPayment(); }
}
// 调用方不调工厂，容器按条件装配后注入 Payment
